const body = pm.response.json();
const location = body.data && body.data.location;

pm.test("HTTP status is 200", function () {
  pm.response.to.have.status(200);
});

pm.test("GraphQL returned no errors", function () {
  pm.expect(body.errors).to.be.undefined;
});

pm.test("Location was found", function () {
  pm.expect(location).to.be.an("object");
});

if (location) {
  pm.test("Returned ID matches the saved ID", function () {
    pm.expect(Number(location.id)).to.eql(
      Number(pm.collectionVariables.get("gql_location_id"))
    );
  });

  pm.test("Returned name matches the generated name", function () {
    pm.expect(location.name).to.eql(
      pm.collectionVariables.get("gql_location_name")
    );
  });
}

